import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { moduleResolver } from './production-files.mjs';

const project = {};

beforeAll(() => {
  project.root = mkdtempSync(path.join(tmpdir(), 'nitpicker-production-files-'));
  mkdirSync(path.join(project.root, 'src/api'), { recursive: true });
  writeFileSync(
    path.join(project.root, 'src/api/client.ts'),
    '// Code generated by openapi-generator. DO NOT EDIT.\nexport const value = 0;\n',
  );
});

afterAll(() => {
  rmSync(project.root, { recursive: true, force: true });
});

function moduleOf(file, policy = {}) {
  return moduleResolver({ projectRoot: project.root, files: [file], policy })(file);
}

describe('moduleResolver', () => {
  it.each([
    ['src/billing/invoice.ts', 'src/billing'],
    ['src/testing/clock.ts', 'src/testing'],
    ['src/fixtures/loader.py', 'src/fixtures'],
    ['pkg/orders/service.py', 'pkg/orders'],
    ['src/main/java/com/acme/billing/Invoice.java', 'src/main/java/com/acme/billing'],
    ['src/main/java/com/acme/test/Probe.java', 'src/main/java/com/acme/test'],
    ['app/src/main/kotlin/com/acme/pay/Pay.kt', 'app/src/main/kotlin/com/acme/pay'],
    ['src/features/billing/model/invoice.ts', 'src/features/billing'],
    ['internal/orders/service.go', 'internal/orders'],
  ])('puts production file %s in %s', (file, module) => {
    expect(moduleOf(file)).toBe(module);
  });

  it.each([
    'src/billing/invoice.test.ts',
    'src/billing/invoice.spec.tsx',
    'tests/billing/test_invoice.py',
    'pkg/orders/test_service.py',
    'pkg/orders/service_test.py',
    'pkg/orders/conftest.py',
    'pkg/orders/tests.py',
    'src/test/java/com/acme/billing/InvoiceTest.java',
    'src/main/java/com/acme/billing/InvoiceIT.java',
    'app/src/test/kotlin/com/acme/pay/PaySpec.kt',
    'app/src/testFixtures/kotlin/com/acme/pay/Fakes.kt',
    'app/src/integrationTest/kotlin/com/acme/pay/Flow.kt',
    'app/src/jvmTest/kotlin/com/acme/pay/Flow.kt',
    'src/__tests__/page.ts',
    'fixtures/orders/sample.ts',
    'testing/helpers.py',
    'internal/orders/service_test.go',
    'internal/orders/testdata/sample.go',
  ])('treats %s as a test', (file) => {
    expect(moduleOf(file)).toBeUndefined();
  });

  it.each([
    'build.gradle.kts',
    'app/build.gradle.kts',
    'settings.gradle.kts',
    'app/vite.config.ts',
    'jest.config.cjs',
    'packages/web/eslint.config.mjs',
    'packages/web/.eslintrc.js',
    'setup.py',
    'app/build/generated/source/Api.kt',
    'web/out/bundle.js',
    'target/classes/Main.java',
    'src/types/api.d.mts',
    'src/types/api.d.cts',
    'src/proto/orders_pb2.py',
    'internal/proto/orders.pb.go',
    'vendor/github.com/acme/lib/lib.go',
    'src/api/client.ts',
    'docs/guide.md',
    'main.ts',
  ])('keeps build, config, generated and root files out: %s', (file) => {
    expect(moduleOf(file)).toBeUndefined();
  });

  it('honours the declared test roots and generated files', () => {
    expect([
      moduleOf('qa/checks/flow.ts', { layout: { testRoots: ['qa'] } }),
      moduleOf('src/billing/schema.ts', { generatedFiles: ['src/billing/schema.ts'] }),
    ]).toEqual([undefined, undefined]);
  });

  it('ignores a file that is not in the listed tree', () => {
    const resolve = moduleResolver({ projectRoot: project.root, files: [], policy: {} });

    expect(resolve('src/billing/invoice.ts')).toBeUndefined();
  });
});
